# Generated by xc --completion powershell. Compatible with PowerShell 5.1/7+.
$__xcmdPython = @PYTHON@
$__xcmdRunner = @RUNNER@
$__xcmdCompleter = {
    param($wordToComplete, $commandAst, $cursorPosition)
    $elements = @($commandAst.CommandElements)
    $index = $elements.Count - 1
    if ($cursorPosition -gt $commandAst.Extent.EndOffset) { $index++ }
    if ($index -gt 1) {
        if ($index -ne 2 -or $elements[1].Value -ne '--show') { return }
    }
    if ($wordToComplete.StartsWith('-')) {
        $options = @('--list', '--show', '--config', '--init', '--edit', '--completion',
                     '--install-completion', '--shell', '--version', '--help')
        foreach ($option in $options) {
            if ($option.StartsWith($wordToComplete, [StringComparison]::Ordinal)) {
                [System.Management.Automation.CompletionResult]::new($option, $option, 'ParameterValue', $option)
            }
        }
        return
    }
    $previousEncoding = [Console]::OutputEncoding
    try {
        [Console]::OutputEncoding = New-Object System.Text.UTF8Encoding $false
        $json = & $__xcmdPython $__xcmdRunner --complete-json $wordToComplete 2>$null
        if ($LASTEXITCODE -ne 0) { return }
        $items = ConvertFrom-Json -InputObject ($json -join "`n")
        foreach ($item in $items) {
            $label = $item.name + ' -- ' + $item.command
            [System.Management.Automation.CompletionResult]::new($item.name, $label, 'ParameterValue', $item.command)
        }
    } finally {
        [Console]::OutputEncoding = $previousEncoding
    }
}.GetNewClosure()
Register-ArgumentCompleter -CommandName xc,xc.exe,xcmd,xcmd.exe -ScriptBlock $__xcmdCompleter
Remove-Variable __xcmdPython,__xcmdRunner,__xcmdCompleter
